import{_ as a,o as r,c as i,a5 as s}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 59 话 渲染时序：rAF、ResizeObserver 循环与任务切分","description":"","frontmatter":{},"headers":[],"relativePath":"comics/mechanism/EP.59-render-timing.md","filePath":"comics/mechanism/EP.59-render-timing.md","lastUpdated":1793853676000}'),t={name:"comics/mechanism/EP.59-render-timing.md"};function o(n,e,l,d,h,c){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="漫画-·-第-59-话-渲染时序-raf、resizeobserver-循环与任务切分" tabindex="-1">漫画 · 第 59 话 渲染时序：rAF、ResizeObserver 循环与任务切分 <a class="header-anchor" href="#漫画-·-第-59-话-渲染时序-raf、resizeobserver-循环与任务切分" aria-label="Permalink to &quot;漫画 · 第 59 话 渲染时序：rAF、ResizeObserver 循环与任务切分&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/mechanism/05-render-timing-raf">docs/mechanism/05-render-timing-raf.md</a> ｜ 原画：<a href="./EP.59-render-timing.svg">EP.59-render-timing.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她的图表页一加载就白屏，缩放窗口还报 <code>ResizeObserver loop</code>。</li><li><strong>标签君</strong>：结构师。负责把事件循环、rAF、ResizeObserver 回调与任务切分排到同一条时间轴上。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱的大屏同步计算 40 万数据点，初始化函数一口气跑 900ms，加载中点什么都没反应。更糟的是 ResizeObserver 回调里直接改图表容器宽度，浏览器不断重排，控制台刷出循环错误。标签君把任务切成 8ms 一片、在片间 rAF 让出，并让 ResizeObserver 只记录尺寸、下一帧再写。首屏可交互时间从 1.8s 降到 0.7s。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>同步初始化把主线程占满，输入事件只能排队；用户感觉“点了没反应”，其实是回调还没轮到。ResizeObserver 在布局后触发，回调里改被观察尺寸会让浏览器再次布局、再次回调，规范用循环深度限制兜底，于是报错。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>一帧顺序：宏任务 → 微任务 → rAF → Style → Layout → Paint → 合成 → 空闲回调。rAF 在布局前执行，适合写样式；微任务会饿死渲染；setTimeout 不对齐帧。任务切分把长计算拆成小片，片间用 rAF 或 scheduler.yield 让出，总时长不变，但输入有机会插队。ResizeObserver 回调应只记录，写入放下一帧并做幂等判断。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>像素酱的修复：数据清洗按 20ms 预算分片；首屏只渲染可视图表；ResizeObserver 记录尺寸后 rAF 统一重排；容器加 <code>contain:layout paint</code>。结果首屏 0.7s 可交互，循环错误归零，缩放不掉帧。她没有减少计算量，只是把任务切成了浏览器能呼吸的粒度。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>rAF 在样式/布局前执行，适合写动画；回调内读写要分离。</li><li>ResizeObserver 回调里改被观察尺寸会触发循环；只记录，下一帧写。</li><li>长任务 &gt;50ms 就会阻塞输入；切分到 5–20ms 一片并让出。</li><li><code>scheduler.yield</code> 优先，<code>setTimeout(0)</code> 只作降级；rIC 不能保证按时。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把 600ms 的计算切成 8ms 一片后，为什么用户仍可能觉得“慢”？</p><p><strong>答</strong>：切分改善的是响应性，不是总时长。如果 600ms 的计算本身必要，首屏结果仍要等 600ms 才完整；用户感知的“快”来自先出现可用内容（首屏优先渲染）与可交互（点击有反馈）。要同时做优先级：关键内容先算，非关键延后到空闲时段。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>rAF 帧率、长任务 vs 分片、ResizeObserver 危险/安全模式：<a href="./../../examples/mechanism/05-render-timing-raf">examples/mechanism/05-render-timing-raf</a></li><li>在长任务运行时连续点击“响应测试”，对比分片模式的延迟。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>机制篇收官。第 60 话起进入组合场景：《组件级响应式：容器查询 + 子网格 + 逻辑属性》——把组件做成真正自包含的积木。</p>',22)])])}const b=a(t,[["render",o]]);export{u as __pageData,b as default};
